select ltcr.id, ltcr.platform_type as platformType, ltcr.logistics_supplier_id as logisticsSupplierId, ltcr.logistics_supplier_name as logisticsSupplierName, ltcr.logistics_channel_id as logisticsChannelId, ltcr.logistics_channel_name as logisticsChannelName, ltcr.logistics_channel_code as logisticsChannelCode, ltcr.third_supplier_code as thirdSupplierCode, ltcr.third_supplier_name as thirdSupplierName, ltcr.third_channel_code as thirdChannelCode, ltcr.third_channel_name as thirdChannelName, ltcr.is_push_mobile as isPushMobile, ltcr.push_type as pushType, ltcr.create_user_name as createUserName, ltcr.create_time as createTime, ltcr.disabled as disabled, ltcr.dict_platform as mainDictPlatform, ltcrd.id as detailId, ltcrd.shop_id as shopId, ltcrd.shop_name as shopName, ltcrd.dict_platform as dictPlatform, ltcrd.mobile as mobile from logistics_third_channel_ref ltcr left join logistics_third_channel_ref_detail ltcrd on ltcr.id = ltcrd.main_id and ltcrd.is_deleted = false
${params.sqlMap.default} and ltcr.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ltcr.create_time desc

SELECT ltcr.ID AS thirdRefId, lbd.ID AS logisticsBillDetailId, lbd.track_no AS trackNo, ltcr.platform_type AS platformType, ltcr.third_channel_code AS thirdChannelCode FROM logistics_bill_detail lbd LEFT JOIN logistics_third_channel_ref ltcr ON ltcr.disabled = FALSE AND ltcr.is_deleted = FALSE AND ltcr.ID = lbd.third_ref_id WHERE lbd.is_deleted = FALSE
AND lbd.track_no IN
#{item}
